using System;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "SyzygyStarOmenData", menuName = "Data/Battle/Omens System/Omen Data/Any/SyzygyStar Omen Data")]
public class SyzygyStarOmenData : IncreasePurifyReceivedByEnemiesOmenData
{
	public override void Initialize(OmenInstance omenInstance)
	{
		Action<GameObject> onEnemyPurifiedSyzygyStarDealCorruptionOmenAction = delegate(GameObject enemy)
		{
			ActivateOmen(enemy);
			omenInstance.EnqueueOmenFeedbackAndPlay();
		};
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyPurifiedSyzygyStarDealCorruptionOmenAction = onEnemyPurifiedSyzygyStarDealCorruptionOmenAction;
		base.Initialize(omenInstance);
	}

	public override void OmenRemoved()
	{
		ReferenceSingleton<PurifyOmensHandler>.Instance.OnEnemyPurifiedSyzygyStarDealCorruptionOmenAction = null;
		base.OmenRemoved();
	}

	public override string OmenConvertedDescription()
	{
		return GetIncreasePurifyReceivedByEnemiesLocalizedString() + "\n" + Smart.Format(GetOmenRawLocalizedDescription(), ActionValue);
	}
}
